        "<strong>The first commandment to a leader.</strong> Joshua’s commission opens not with military instruction but with Torah-meditation. The verb <em>hagah</em> (“meditate”) means to murmur or recite under one’s breath — Torah study as a continuous bodily practice, not silent reading. Psalm 1:2 echoes this verse almost verbatim, transferring the leader’s discipline to every righteous person. The juxtaposition is striking: Israel’s most aggressive military campaign begins with an order to recite a book.",
