        "comm",
        "Note",
        "Note",
        "<strong>Rahab the Canaanite.</strong> A Canaanite woman, a prostitute, who hides Israelite spies and bargains for her family’s survival. The narrative protects her actively — she is the chapter’s moral center despite being a triple outsider (Canaanite, woman, sex worker). Matthew 1:5 lists her in the genealogy of Jesus; Hebrews 11:31 names her among the heroes of faith; James 2:25 cites her alongside Abraham as a model of justifying works. The book of Joshua contains both <em>ḥerem</em> (devoted destruction) and Rahab’s rescue — its theology is more layered than its surface campaign narrative suggests.",
        "User original",
