    (
        14,
        9,
        "",
        "because you have wholly followed Yahweh my God",
        "comm",
        "Note",
        "Note",
        "<strong>Caleb’s portion.</strong> The Kenizzite Caleb (a non-Israelite by ancestry — see Num 32:12, Josh 14:6) receives Hebron as his inheritance for fidelity at Kadesh-barnea forty-five years earlier (14:10). The narrative quietly preserves the genealogical complexity of early Israel: a non-Israelite of demonstrated loyalty receives one of the most sacred sites in the land — the patriarchal burial place at Machpelah. The Caleb tradition coexists with the more rigid genealogical boundaries of later texts.",
        "User original",
    ),
