    (
        24,
        15,
        "",
        "choose today whom you will serve",
        "comm-contextual",
        "Note",
        "Note",
        "<strong>The Shechem covenant.</strong> Joshua’s farewell ceremony at Shechem (24:1–28) reads as a covenant renewal in formal ancient Near Eastern shape: historical prologue (24:2–13), stipulations (24:14–15), people’s acceptance (24:16–18), warning (24:19–20), witnesses (24:22, 27), written record (24:25–26), monument (24:26b–27). The same pattern underlies the Sinai covenant in Exodus and the Hittite suzerainty treaties of the second millennium BCE. The “for me and my house” formula (24:15) has become one of the most-quoted lines in the book.",
        "User original",
    ),
